use canlang_compiler::{analysis::check_program, source::{SourceDb,SourceId}, syntax::parse_source};
use serde_json::json;
fn main(){ let path=std::env::args().nth(1).unwrap(); let text=std::fs::read_to_string(&path).unwrap(); let (tree, ds)=parse_source(SourceId(0),&text); let mut db=SourceDb::new(); let id=db.add(path,text.clone()); let (program, ads)=check_program(&db,&[id],None); println!("{}",json!({"coverage":tree.verify_coverage(text.len() as u32).is_ok(),"nodes":tree.descendants().map(|n|json!({"kind":format!("{:?}",n.kind),"start":n.span.start,"end":n.span.end})).collect::<Vec<_>>(),"parse":ds.iter().map(|d|json!({"code":d.code,"start":d.primary.start,"end":d.primary.end})).collect::<Vec<_>>(),"diagnostics":ads.iter().map(|d|json!({"code":d.code,"start":d.primary.start,"end":d.primary.end})).collect::<Vec<_>>(),"modules":program.modules.iter().map(|m|&m.name).collect::<Vec<_>>(),"symbols":program.symbols.iter().map(|s|&s.canonical).collect::<Vec<_>>() })); }
